/// The icon of a name the app calls it by (myzig's), or null.
pub fn named(name: []const u8) ?Icon {
    const map = [_]struct { []const u8, Icon }{
        .{ "xmark", .x },
        .{ "plus", .plus },
        .{ "minus", .minus },
        .{ "chevron.down", .chevron_down },
        .{ "chevron.up", .chevron_up },
        .{ "chevron.left", .chevron_left },
        .{ "chevron.right", .chevron_right },
        .{ "folder", .folder },
        .{ "folder.open", .folder_open },
        .{ "doc", .file },
        .{ "doc.text", .open_file },
        .{ "doc.on.doc", .files },
        .{ "plus.square", .file_plus },
        .{ "folder.badge.plus", .folder_plus },
        .{ "photo", .image },
        .{ "terminal", .terminal },
        .{ "trash", .trash },
        .{ "magnifyingglass", .search },
        .{ "arrow.up", .arrow_up },
        .{ "arrow.down", .arrow_down },
        .{ "arrow.triangle.branch", .branch },
        .{ "globe", .branch },
        .{ "arrow.clockwise", .refresh },
        .{ "arrow.uturn.backward", .undo },
        .{ "rectangle.on.rectangle", .collapse },
        .{ "pencil", .pencil },
        .{ "checkmark", .check },
        .{ "hand.raised", .lock },
        .{ "lock", .lock },
        .{ "wrench.and.screwdriver", .gear },
        .{ "gear", .gear },
        .{ "arrow.up.right", .to_editor },
        .{ "arrow.up.left.and.arrow.down.right", .maximize },
        .{ "arrow.down.right.and.arrow.up.left", .minimize },
        .{ "cube", .box },
        .{ "textformat", .type },
        .{ "chevron.left.forwardslash.chevron.right", .function },
        .{ "circle", .hash },
        .{ "clock", .clock },
        .{ "tag", .tag },
        .{ "ellipsis", .more },
        .{ "square.and.arrow.up", .push },
        .{ "square.and.arrow.down", .pull },
        .{ "icloud.and.arrow.down", .fetch },
        .{ "text.bubble", .comment },
        .{ "paperplane", .send },
        .{ "sidebar.left", .sidebar },
        .{ "sidebar.right", .sidebar_right },
        .{ "rectangle.bottomthird.inset.filled", .panel },
        .{ "wrap", .wrap },
        .{ "diff", .diff },
        .{ "columns", .columns },
        .{ "rows", .rows },
        .{ "keyboard", .keyboard },
        .{ "commit", .commit },
        .{ "unfold", .unfold },
    };
    for (map) |e| if (@import("std").mem.eql(u8, e[0], name)) return e[1];
    // Else the Go app's own name, as `replace_all`.
    return @import("std").meta.stringToEnum(Icon, name);
}
